rtl:
always_comb begin
  case (state)
    IDLE:    if (start) next = STARTUP;
    STARTUP: next = RUNNING;
    // RUNNING and ERROR have no branches — FSM trapped
  endcase
end

fix_replacement:
always_comb begin
  next = state;  // Hold by default
  case (state)
    IDLE:    if (start) next = STARTUP;
    STARTUP: next = RUNNING;
    RUNNING: if (stop || fault) next = IDLE;
    ERROR:   next = IDLE;
    default: next = IDLE;
  endcase
end
